import{_ as i,C as b,o as a,c as r,a2 as e,b as s,w as d,a as o,E as l,a3 as c}from"./chunks/framework.CZqXuAiL.js";const f=JSON.parse('{"title":"Bandwidth Manager","description":"Production-grade Docker bandwidth management with per-container speed limits, daily traffic quotas, and kernel-level tc enforcement.","frontmatter":{"title":"Bandwidth Manager","description":"Production-grade Docker bandwidth management with per-container speed limits, daily traffic quotas, and kernel-level tc enforcement.","head":[["meta",{"name":"og:title","content":"Bandwidth Manager — Docker Traffic Control"}],["meta",{"name":"og:description","content":"Per-container speed limits, daily quotas, kernel-level tc enforcement, webhook notifications. Built for production."}]]},"headers":[],"relativePath":"bandwidth-manager/index.md","filePath":"bandwidth-manager/index.md","lastUpdated":null}'),v={name:"bandwidth-manager/index.md"};function h(g,t,p,u,m,y){const n=b("Mermaid");return a(),r("div",null,[t[1]||(t[1]=e(`<h1 id="bandwidth-manager" tabindex="-1" data-v-b6d6639b>Bandwidth Manager <a class="header-anchor" href="#bandwidth-manager" aria-label="Permalink to &quot;Bandwidth Manager&quot;" data-v-b6d6639b>​</a></h1><p data-v-b6d6639b><strong data-v-b6d6639b>Production-grade Docker bandwidth management</strong> — per-container speed limits, daily traffic quotas, kernel‑level <code data-v-b6d6639b>tc</code> enforcement.</p><p data-v-b6d6639b>Stop guessing which container is saturating your uplink. Bandwidth Manager gives you surgical control over every container&#39;s network throughput — programmatically, persistently, and with zero userspace throttling overhead.</p><div class="tip custom-block" style="margin-top:1.5rem;" data-v-b6d6639b><p data-v-b6d6639b><strong data-v-b6d6639b>🎯 Built for PingLess Studios by <a href="https://github.com/AnAverageBeing" target="_blank" rel="noreferrer" data-v-b6d6639b>AnAverageBeing</a></strong><br data-v-b6d6639b><a href="https://github.com/AnAverageBeing/Bandwidth-flow-maintainer" target="_blank" rel="noreferrer" data-v-b6d6639b>GitHub Repo</a> · <code data-v-b6d6639b>MIT License</code></p></div><hr data-v-b6d6639b><h2 id="why-bandwidth-manager" tabindex="-1" data-v-b6d6639b>Why Bandwidth Manager? <a class="header-anchor" href="#why-bandwidth-manager" aria-label="Permalink to &quot;Why Bandwidth Manager?&quot;" data-v-b6d6639b>​</a></h2><p data-v-b6d6639b>Running multiple Docker containers on a single host means one noisy neighbour can starve everyone else. Traditional solutions are painful:</p><table tabindex="0" data-v-b6d6639b><thead data-v-b6d6639b><tr data-v-b6d6639b><th data-v-b6d6639b>Approach</th><th data-v-b6d6639b>Pain Point</th></tr></thead><tbody data-v-b6d6639b><tr data-v-b6d6639b><td data-v-b6d6639b><strong data-v-b6d6639b>Manual <code data-v-b6d6639b>tc</code></strong></td><td data-v-b6d6639b>Steep learning curve, ephemeral rules lost on reboot, no per‑container visibility</td></tr><tr data-v-b6d6639b><td data-v-b6d6639b><strong data-v-b6d6639b>cgroups v2</strong></td><td data-v-b6d6639b>Inconsistent across kernel versions, no daily quota concept, poor tooling</td></tr><tr data-v-b6d6639b><td data-v-b6d6639b><strong data-v-b6d6639b>Docker Compose <code data-v-b6d6639b>deploy.resources.limits</code></strong></td><td data-v-b6d6639b>Swarm-only, ignores standalone containers, no traffic accounting</td></tr><tr data-v-b6d6639b><td data-v-b6d6639b><strong data-v-b6d6639b>Thick SaaS agents</strong></td><td data-v-b6d6639b>Expensive, closed-source, heavy on RAM</td></tr></tbody></table><p data-v-b6d6639b>Bandwidth Manager fills the gap with a <strong data-v-b6d6639b>single static binary</strong>, a handful of Docker labels, and the Linux kernel&#39;s battle-tested Traffic Control subsystem.</p><hr data-v-b6d6639b><h2 id="key-features" tabindex="-1" data-v-b6d6639b>Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;" data-v-b6d6639b>​</a></h2><h3 id="🚦-per-container-speed-limiting" tabindex="-1" data-v-b6d6639b>🚦 Per-Container Speed Limiting <a class="header-anchor" href="#🚦-per-container-speed-limiting" aria-label="Permalink to &quot;🚦 Per-Container Speed Limiting&quot;" data-v-b6d6639b>​</a></h3><p data-v-b6d6639b>Set upload and download rate limits <strong data-v-b6d6639b>per container</strong> via Docker labels. No config files, no sidecars.</p><div class="language-yaml vp-adaptive-theme" data-v-b6d6639b><button title="Copy Code" class="copy" data-v-b6d6639b></button><span class="lang" data-v-b6d6639b>yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0" data-v-b6d6639b><code data-v-b6d6639b><span class="line" data-v-b6d6639b><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;" data-v-b6d6639b>labels</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;" data-v-b6d6639b>:</span></span>
<span class="line" data-v-b6d6639b><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;" data-v-b6d6639b>  bwm.limit.down</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;" data-v-b6d6639b>: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;" data-v-b6d6639b>&quot;50mbps&quot;</span></span>
<span class="line" data-v-b6d6639b><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;" data-v-b6d6639b>  bwm.limit.up</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;" data-v-b6d6639b>:   </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;" data-v-b6d6639b>&quot;10mbps&quot;</span></span></code></pre></div><h3 id="📊-daily-traffic-quotas" tabindex="-1" data-v-b6d6639b>📊 Daily Traffic Quotas <a class="header-anchor" href="#📊-daily-traffic-quotas" aria-label="Permalink to &quot;📊 Daily Traffic Quotas&quot;" data-v-b6d6639b>​</a></h3><p data-v-b6d6639b>Define a total data allowance that resets at midnight (configurable). Containers that exceed their quota are throttled to a trickle until the next reset window.</p><div class="language-yaml vp-adaptive-theme" data-v-b6d6639b><button title="Copy Code" class="copy" data-v-b6d6639b></button><span class="lang" data-v-b6d6639b>yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0" data-v-b6d6639b><code data-v-b6d6639b><span class="line" data-v-b6d6639b><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;" data-v-b6d6639b>labels</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;" data-v-b6d6639b>:</span></span>
<span class="line" data-v-b6d6639b><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;" data-v-b6d6639b>  bwm.quota.daily</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;" data-v-b6d6639b>: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;" data-v-b6d6639b>&quot;5gb&quot;</span></span></code></pre></div><h3 id="🔍-automatic-container-discovery" tabindex="-1" data-v-b6d6639b>🔍 Automatic Container Discovery <a class="header-anchor" href="#🔍-automatic-container-discovery" aria-label="Permalink to &quot;🔍 Automatic Container Discovery&quot;" data-v-b6d6639b>​</a></h3><p data-v-b6d6639b>Listens to the Docker event stream. New containers get rules applied immediately. Stopped containers get cleaned up. No polling, no cron.</p><h3 id="⚡-kernel-level-tc-enforcement" tabindex="-1" data-v-b6d6639b>⚡ Kernel-Level <code data-v-b6d6639b>tc</code> Enforcement <a class="header-anchor" href="#⚡-kernel-level-tc-enforcement" aria-label="Permalink to &quot;⚡ Kernel-Level \`tc\` Enforcement&quot;" data-v-b6d6639b>​</a></h3><p data-v-b6d6639b>All shaping runs through the Linux <code data-v-b6d6639b>tc</code> (Traffic Control) subsystem via <code data-v-b6d6639b>htb</code> qdiscs and <code data-v-b6d6639b>fq_codel</code> inner qdiscs attached to veth pairs. <strong data-v-b6d6639b>Zero userspace throttling</strong> — the kernel does the heavy lifting, so CPU overhead is negligible even at multi‑gigabit rates.</p><h3 id="🏷️-docker-label-overrides" tabindex="-1" data-v-b6d6639b>🏷️ Docker Label Overrides <a class="header-anchor" href="#🏷️-docker-label-overrides" aria-label="Permalink to &quot;🏷️ Docker Label Overrides&quot;" data-v-b6d6639b>​</a></h3><p data-v-b6d6639b>Every setting can be driven by Docker container labels. Tweak limits without restarting the daemon — just update the label and send <code data-v-b6d6639b>SIGHUP</code>.</p><h3 id="🔔-webhook-notifications" tabindex="-1" data-v-b6d6639b>🔔 Webhook Notifications <a class="header-anchor" href="#🔔-webhook-notifications" aria-label="Permalink to &quot;🔔 Webhook Notifications&quot;" data-v-b6d6639b>​</a></h3><p data-v-b6d6639b>Fire alerts to <strong data-v-b6d6639b>Discord</strong> or <strong data-v-b6d6639b>Slack</strong> when containers hit quota thresholds or when the daemon state changes. Includes a rich embed payload.</p><h3 id="🖥️-modern-terminal-ui" tabindex="-1" data-v-b6d6639b>🖥️ Modern Terminal UI <a class="header-anchor" href="#🖥️-modern-terminal-ui" aria-label="Permalink to &quot;🖥️ Modern Terminal UI&quot;" data-v-b6d6639b>​</a></h3><p data-v-b6d6639b>A beautiful, keyboard‑driven TUI built with <a href="https://github.com/charmbracelet/bubbletea" target="_blank" rel="noreferrer" data-v-b6d6639b>Bubble Tea</a>. Inspect live rates, quotas, and rule status in real time. Sort, filter, and drill down — all from your terminal.</p><h3 id="📈-historical-stats" tabindex="-1" data-v-b6d6639b>📈 Historical Stats <a class="header-anchor" href="#📈-historical-stats" aria-label="Permalink to &quot;📈 Historical Stats&quot;" data-v-b6d6639b>​</a></h3><p data-v-b6d6639b>Per‑container byte counters and rate samples persisted to <strong data-v-b6d6639b>SQLite</strong> (zero external dependencies). Query with the CLI or export to CSV for Grafana.</p><h3 id="🧩-sqlite-backend-—-zero-external-dependencies" tabindex="-1" data-v-b6d6639b>🧩 SQLite Backend — Zero External Dependencies <a class="header-anchor" href="#🧩-sqlite-backend-—-zero-external-dependencies" aria-label="Permalink to &quot;🧩 SQLite Backend — Zero External Dependencies&quot;" data-v-b6d6639b>​</a></h3><p data-v-b6d6639b>No Postgres, no Redis, no message queues. Everything lives in a single <code data-v-b6d6639b>bandwidth.db</code> file. Back it up with <code data-v-b6d6639b>rsync</code> and sleep easy.</p><h3 id="🔧-systemd-integration" tabindex="-1" data-v-b6d6639b>🔧 Systemd Integration <a class="header-anchor" href="#🔧-systemd-integration" aria-label="Permalink to &quot;🔧 Systemd Integration&quot;" data-v-b6d6639b>​</a></h3><p data-v-b6d6639b>Ships with a hardened systemd unit. Socket activation, <code data-v-b6d6639b>ProtectSystem=strict</code>, <code data-v-b6d6639b>NoNewPrivileges</code>, and automatic restarts.</p><hr data-v-b6d6639b><h2 id="quick-install" tabindex="-1" data-v-b6d6639b>Quick Install <a class="header-anchor" href="#quick-install" aria-label="Permalink to &quot;Quick Install&quot;" data-v-b6d6639b>​</a></h2><div class="language-bash vp-adaptive-theme" data-v-b6d6639b><button title="Copy Code" class="copy" data-v-b6d6639b></button><span class="lang" data-v-b6d6639b>bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0" data-v-b6d6639b><code data-v-b6d6639b><span class="line" data-v-b6d6639b><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;" data-v-b6d6639b>curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;" data-v-b6d6639b> -sSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;" data-v-b6d6639b> https://raw.githubusercontent.com/AnAverageBeing/Bandwidth-flow-maintainer/main/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;" data-v-b6d6639b> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;" data-v-b6d6639b> sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;" data-v-b6d6639b> bash</span></span></code></pre></div><p data-v-b6d6639b>That&#39;s it. The script installs the binary, drops in a systemd unit, and starts the daemon. Head over to <a href="./getting-started/installation" data-v-b6d6639b>Installation</a> for the full walkthrough and manual install instructions.</p><hr data-v-b6d6639b><h2 id="architecture" tabindex="-1" data-v-b6d6639b>Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;" data-v-b6d6639b>​</a></h2>`,39)),(a(),s(c,null,{default:d(()=>[l(n,{id:"mermaid-148",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20subgraph%20Host%5B%22Host%20(Container%20Runtime)%22%5D%0A%20%20%20%20%20%20%20%20direction%20TB%0A%20%20%20%20%20%20%20%20DE%5B%22Docker%20Engine%20%2Fcontainerd%22%5D%0A%20%20%20%20%20%20%20%20DE%20--%3E%7C%22event%20stream%22%7C%20DISC%5B%22Container%20Discovery%22%5D%0A%20%20%20%20%20%20%20%20DISC%20--%3E%7C%22label%20parsing%22%7C%20RULES%5B%22Rule%20Builder%22%5D%0A%20%20%20%20%20%20%20%20RULES%20--%3E%7C%22htb%20%2B%20fq_codel%22%7C%20TC%5B%22tc%20Subsystem%22%5D%0A%20%20%20%20%20%20%20%20TC%20--%3E%7C%22attached%20to%22%7C%20VETH%5B%22veth%20Pairs%22%5D%0A%20%20%20%20%20%20%20%20VETH%20--%3E%20C1%5B%22Container%20A%22%5D%0A%20%20%20%20%20%20%20%20VETH%20--%3E%20C2%5B%22Container%20B%22%5D%0A%20%20%20%20%20%20%20%20VETH%20--%3E%20C3%5B%22Container%20C%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20Userspace%5B%22Userspace%20Layer%22%5D%0A%20%20%20%20%20%20%20%20direction%20TB%0A%20%20%20%20%20%20%20%20CLI%5B%22bwm%20CLI%22%5D%20--%3E%7C%22gRPC%20%2F%20HTTP%22%7C%20SOCKET%5B%22Unix%20Socket%22%5D%0A%20%20%20%20%20%20%20%20TUI%5B%22bwm%20tui%22%5D%20--%3E%20SOCKET%0A%20%20%20%20%20%20%20%20SOCKET%20--%3E%20DAEMON%5B%22bwm-daemon%22%5D%0A%20%20%20%20%20%20%20%20DAEMON%20--%3E%20DE%0A%20%20%20%20%20%20%20%20DAEMON%20--%3E%20SQLITE%5B%22bandwidth.db%22%5D%0A%20%20%20%20%20%20%20%20DAEMON%20--%3E%20WEBHOOK%5B%22Webhook%20Dispatcher%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20Host%20--%3E%20Userspace%0A%20%20%20%20WEBHOOK%20--%3E%20DISCORD%5B%22Discord%22%5D%0A%20%20%20%20WEBHOOK%20--%3E%20SLACK%5B%22Slack%22%5D%0A"})]),fallback:d(()=>[...t[0]||(t[0]=[o(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=e('<h3 id="control-flow" tabindex="-1" data-v-b6d6639b>Control Flow <a class="header-anchor" href="#control-flow" aria-label="Permalink to &quot;Control Flow&quot;" data-v-b6d6639b>​</a></h3><table tabindex="0" data-v-b6d6639b><thead data-v-b6d6639b><tr data-v-b6d6639b><th data-v-b6d6639b>Path</th><th data-v-b6d6639b>Description</th></tr></thead><tbody data-v-b6d6639b><tr data-v-b6d6639b><td data-v-b6d6639b><strong data-v-b6d6639b>Docker → Discovery</strong></td><td data-v-b6d6639b>Daemon subscribes to <code data-v-b6d6639b>/events</code>. Container create/destroy triggers re‑eval.</td></tr><tr data-v-b6d6639b><td data-v-b6d6639b><strong data-v-b6d6639b>Discovery → Rules</strong></td><td data-v-b6d6639b>Labels are parsed into rate &amp; quota specs. Defaults fill in missing values.</td></tr><tr data-v-b6d6639b><td data-v-b6d6639b><strong data-v-b6d6639b>Rules → tc</strong></td><td data-v-b6d6639b><code data-v-b6d6639b>htb</code> class tree is built per interface; <code data-v-b6d6639b>fq_codel</code> leaf qdiscs handle fairness.</td></tr><tr data-v-b6d6639b><td data-v-b6d6639b><strong data-v-b6d6639b>tc → veth → Container</strong></td><td data-v-b6d6639b>Shaping happens on the host-side veth, so the container has no visibility into the limit — it simply sees a constrained pipe.</td></tr><tr data-v-b6d6639b><td data-v-b6d6639b><strong data-v-b6d6639b>CLI → Unix Socket → Daemon</strong></td><td data-v-b6d6639b>All administrative commands flow over a Unix socket with filesystem ACLs. No network exposure by default.</td></tr></tbody></table><hr data-v-b6d6639b><h2 id="comparison" tabindex="-1" data-v-b6d6639b>Comparison <a class="header-anchor" href="#comparison" aria-label="Permalink to &quot;Comparison&quot;" data-v-b6d6639b>​</a></h2><table tabindex="0" data-v-b6d6639b><thead data-v-b6d6639b><tr data-v-b6d6639b><th data-v-b6d6639b>Capability</th><th style="text-align:center;" data-v-b6d6639b>Bandwidth Manager</th><th style="text-align:center;" data-v-b6d6639b>Manual <code data-v-b6d6639b>tc</code></th><th style="text-align:center;" data-v-b6d6639b>cgroups v2</th><th style="text-align:center;" data-v-b6d6639b>Docker Compose Limits</th></tr></thead><tbody data-v-b6d6639b><tr data-v-b6d6639b><td data-v-b6d6639b>Per‑container rate limit</td><td style="text-align:center;" data-v-b6d6639b>✅</td><td style="text-align:center;" data-v-b6d6639b>✅</td><td style="text-align:center;" data-v-b6d6639b>⚠️ partial</td><td style="text-align:center;" data-v-b6d6639b>✅ (Swarm only)</td></tr><tr data-v-b6d6639b><td data-v-b6d6639b>Daily traffic quota</td><td style="text-align:center;" data-v-b6d6639b>✅</td><td style="text-align:center;" data-v-b6d6639b>❌</td><td style="text-align:center;" data-v-b6d6639b>❌</td><td style="text-align:center;" data-v-b6d6639b>❌</td></tr><tr data-v-b6d6639b><td data-v-b6d6639b>Automatic container discovery</td><td style="text-align:center;" data-v-b6d6639b>✅</td><td style="text-align:center;" data-v-b6d6639b>❌</td><td style="text-align:center;" data-v-b6d6639b>❌</td><td style="text-align:center;" data-v-b6d6639b>❌</td></tr><tr data-v-b6d6639b><td data-v-b6d6639b>Persistent across reboots</td><td style="text-align:center;" data-v-b6d6639b>✅</td><td style="text-align:center;" data-v-b6d6639b>❌</td><td style="text-align:center;" data-v-b6d6639b>✅</td><td style="text-align:center;" data-v-b6d6639b>✅</td></tr><tr data-v-b6d6639b><td data-v-b6d6639b>Docker label driven</td><td style="text-align:center;" data-v-b6d6639b>✅</td><td style="text-align:center;" data-v-b6d6639b>❌</td><td style="text-align:center;" data-v-b6d6639b>❌</td><td style="text-align:center;" data-v-b6d6639b>❌</td></tr><tr data-v-b6d6639b><td data-v-b6d6639b>Webhook notifications</td><td style="text-align:center;" data-v-b6d6639b>✅</td><td style="text-align:center;" data-v-b6d6639b>❌</td><td style="text-align:center;" data-v-b6d6639b>❌</td><td style="text-align:center;" data-v-b6d6639b>❌</td></tr><tr data-v-b6d6639b><td data-v-b6d6639b>Built‑in TUI</td><td style="text-align:center;" data-v-b6d6639b>✅</td><td style="text-align:center;" data-v-b6d6639b>❌</td><td style="text-align:center;" data-v-b6d6639b>❌</td><td style="text-align:center;" data-v-b6d6639b>❌</td></tr><tr data-v-b6d6639b><td data-v-b6d6639b>Historical stats (SQLite)</td><td style="text-align:center;" data-v-b6d6639b>✅</td><td style="text-align:center;" data-v-b6d6639b>❌</td><td style="text-align:center;" data-v-b6d6639b>❌</td><td style="text-align:center;" data-v-b6d6639b>❌</td></tr><tr data-v-b6d6639b><td data-v-b6d6639b>Works on standalone <code data-v-b6d6639b>docker run</code></td><td style="text-align:center;" data-v-b6d6639b>✅</td><td style="text-align:center;" data-v-b6d6639b>✅</td><td style="text-align:center;" data-v-b6d6639b>✅</td><td style="text-align:center;" data-v-b6d6639b>❌</td></tr><tr data-v-b6d6639b><td data-v-b6d6639b>Kernel‑level enforcement</td><td style="text-align:center;" data-v-b6d6639b>✅</td><td style="text-align:center;" data-v-b6d6639b>✅</td><td style="text-align:center;" data-v-b6d6639b>✅</td><td style="text-align:center;" data-v-b6d6639b>❌ (userspace proxy)</td></tr><tr data-v-b6d6639b><td data-v-b6d6639b>Learning curve</td><td style="text-align:center;" data-v-b6d6639b>Low</td><td style="text-align:center;" data-v-b6d6639b>Steep</td><td style="text-align:center;" data-v-b6d6639b>Moderate</td><td style="text-align:center;" data-v-b6d6639b>Low</td></tr></tbody></table><blockquote data-v-b6d6639b><p data-v-b6d6639b><strong data-v-b6d6639b>Bottom line:</strong> If you need simple rate caps <em data-v-b6d6639b>and</em> daily quotas with zero‑touch operation, Bandwidth Manager is purpose‑built for the job.</p></blockquote><hr data-v-b6d6639b><h2 id="next-steps" tabindex="-1" data-v-b6d6639b>Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;" data-v-b6d6639b>​</a></h2><ul data-v-b6d6639b><li data-v-b6d6639b><strong data-v-b6d6639b><a href="./getting-started/installation" data-v-b6d6639b>Installation →</a></strong> — Get up and running in under a minute.</li><li data-v-b6d6639b><strong data-v-b6d6639b><a href="./configuration" data-v-b6d6639b>Configuration →</a></strong> — Learn about labels, quotas, and webhooks.</li><li data-v-b6d6639b><strong data-v-b6d6639b><a href="./cli" data-v-b6d6639b>CLI Reference →</a></strong> — Every command, flag, and exit code.</li><li data-v-b6d6639b><strong data-v-b6d6639b><a href="./tui" data-v-b6d6639b>TUI Guide →</a></strong> — Master the terminal dashboard.</li></ul><hr data-v-b6d6639b><div class="footer-note" data-v-b6d6639b><p data-v-b6d6639b><strong data-v-b6d6639b>Developed by <a href="https://github.com/AnAverageBeing" target="_blank" rel="noreferrer" data-v-b6d6639b>AnAverageBeing</a> for <a href="https://github.com/pingless-studios" target="_blank" rel="noreferrer" data-v-b6d6639b>PingLess Studios</a></strong></p><p data-v-b6d6639b>Crafted with ❤️ and lots of <code data-v-b6d6639b>tc filter add dev …</code> commands.<br data-v-b6d6639b> If this project saves you from a 3 AM pager, consider starring the repo.</p></div>',11))])}const x=i(v,[["render",h],["__scopeId","data-v-b6d6639b"]]);export{f as __pageData,x as default};
